  const views={control:controlView,explorer:explorerView,ai:aiView,devices:deviceView,jobs:jobsView,training:trainingView,cert:certView,media:mediaView,community:communityView,offline:offlineView,faultlab:faultLabView,electronics:electronicsView,boardview:boardviewView,compatibility:compatibilityView,servicesim:serviceSimView};
