  async function cachePack(){const b=q('#gaxCachePack',panel),s=q('#gaxOfflineStatus',panel);b.disabled=true;s.textContent='Pobieram pakiet do pamięci przeglądarki…';try{if(!('caches'in window))throw new Error('Cache Storage nie jest dostępny.');const cache=await caches.open('npa-global-academy-fix77-offline');let done=0;for(const url of OFFLINE_FILES){const r=await fetch(url,{credentials:'same-origin',cache:'no-store'});if(!r.ok)throw new Error(`${url}: HTTP ${r.status}`);await cache.put(url,r.clone());done++;q('#gaxCacheProgress',panel).style.width=`${Math.round(done/OFFLINE_FILES.length*100)}%`;}s.textContent=`Zapisano ${done}/${OFFLINE_FILES.length} zasobów. Pakiet jest dostępny w tym profilu przeglądarki.`;}catch(e){s.textContent=`Pakiet niekompletny: ${e.message}.`;}finally{b.disabled=false;}}
