  async function backupImport(e){const file=e.target.files?.[0];if(!file)return;const status=q('#gaxOfflineStatus',panel);try{if(file.size>2*1024*1024)throw new Error('Kopia przekracza 2 MiB.');const data=JSON.parse(await file.text());if(data.schema!=='npa-fix64-fix77-backup-v1'||!data.data||typeof data.data!=='object')throw new Error('Nieprawidłowy format kopii FIX64–FIX73.');for(const key of Object.values(STORE)){if(!(key in data.data))continue;const incoming=data.data[key];if(key===STORE.path){const old=read(key,{});write(key,{...old,...incoming});}else if(Array.isArray(incoming)){const old=read(key,[]),map=new Map(old.filter(x=>x&&x.id).map(x=>[x.id,x]));incoming.forEach(x=>{if(x&&x.id&&!map.has(x.id))map.set(x.id,x);});write(key,[...map.values()].slice(-500));}}const meta=read(STORE.sync,[]);meta.push({at:new Date().toISOString(),direction:'import',sourceBuild:String(data.build||'unknown')});write(STORE.sync,meta.slice(-50));status.textContent='Import zakończony. Rekordy połączono po identyfikatorach; istniejących wpisów nie nadpisano.';}catch(err){status.textContent=`Import przerwany: ${err.message}`;}finally{e.target.value='';}}
